// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LoginAccount Log in as a creator (app host)
	// (POST /accounts/login)
	LoginAccount(ctx context.Context, request LoginAccountRequestObject) (LoginAccountResponseObject, error)

	// (POST /accounts/logout)
	LogoutAccount(ctx context.Context, request LogoutAccountRequestObject) (LogoutAccountResponseObject, error)

	// (GET /accounts/me)
	GetCurrentAccount(ctx context.Context, request GetCurrentAccountRequestObject) (GetCurrentAccountResponseObject, error)
	// SignupAccount Create a creator account and its first school (app host)
	// (POST /accounts/signup)
	SignupAccount(ctx context.Context, request SignupAccountRequestObject) (SignupAccountResponseObject, error)

	// (POST /auth/login)
	LoginStudent(ctx context.Context, request LoginStudentRequestObject) (LoginStudentResponseObject, error)

	// (POST /auth/logout)
	LogoutStudent(ctx context.Context, request LogoutStudentRequestObject) (LogoutStudentResponseObject, error)
	// SignupStudent Create a student account in the school of the current host
	// (POST /auth/signup)
	SignupStudent(ctx context.Context, request SignupStudentRequestObject) (SignupStudentResponseObject, error)
	// CheckTLSAllowed Edge proxy asks whether it may issue a certificate for a domain (Caddy on_demand_tls ask)
	// (GET /internal/tls-allowed)
	CheckTLSAllowed(ctx context.Context, request CheckTLSAllowedRequestObject) (CheckTLSAllowedResponseObject, error)

	// (GET /me)
	GetCurrentStudent(ctx context.Context, request GetCurrentStudentRequestObject) (GetCurrentStudentResponseObject, error)
	// GetStorefrontSchool Public info for the school served on the current host
	// (GET /storefront/school)
	GetStorefrontSchool(ctx context.Context, request GetStorefrontSchoolRequestObject) (GetStorefrontSchoolResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

